/* ---------------- clock / systick ---------------- */
static void clock_init_48mhz(void)
{
    FLASH_ACR = 0x11;
    RCC_CFGR &= ~(0xF << 18);
    RCC_CFGR |= (10 << 18);
    RCC_CR |= (1 << 24);
    while (!(RCC_CR & (1 << 25)));
    RCC_CFGR &= ~3;
    RCC_CFGR |= 2;
    while ((RCC_CFGR & 0xC) != 0x8);
}

static void systick_init(void)
{
    SYST_RVR = 48000 - 1;     /* 1 ms */
    SYST_CVR = 0;
    SYST_CSR = 5;             /* cpu clock, enabled, no interrupt */
}

static void delay_1ms(void)
{
    (void)SYST_CSR;                          /* clears COUNTFLAG */
    while (!(SYST_CSR & (1u << 16)));
}

static void delay_ms(uint32_t n) { while (n--) delay_1ms(); }

/* ---------------- random ---------------- */
static uint32_t rng = 2463534242u;
static uint16_t rnd(uint16_t n)       /* 0 .. n-1 like BASCOM Rnd() */
{
    rng ^= SYST_CVR;
    if (rng == 0) rng = 1;
    rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5;
    return n ? (uint16_t)(rng % n) : 0;
}

/* ---------------- UART (USART1 + DMA circular RX) ---------------- */
static void uart_init(void)
{
    RCC_APB2ENR |= (1 << 14);
    GPIOA_MODER &= ~((3 << (9 * 2)) | (3 << (10 * 2)));
    GPIOA_MODER |=  ((2 << (9 * 2)) | (2 << (10 * 2)));
    GPIOA_AFRH  &= ~((0xF << 4) | (0xF << 8));
    GPIOA_AFRH  |=  ((1 << 4) | (1 << 8));

    DMA1_CCR3   = 0;
    DMA1_CPAR3  = 0x40013824;                    /* USART1_RDR */
    DMA1_CMAR3  = (uint32_t)rxbuf;
    DMA1_CNDTR3 = RXBUF_SIZE;
    DMA1_CCR3   = (1 << 7) | (1 << 5) | 1;       /* MINC | CIRC | EN */

    USART1_BRR = 48000000 / 9600;
    USART1_CR3 = (1 << 6) | (1 << 12);           /* DMAR | OVRDIS */
    USART1_CR1 = (1 << 0) | (1 << 2) | (1 << 3); /* UE | RE | TE */
}

static void uart_puts(const char *s)
{
    while (*s) {
        while (!(USART1_ISR & (1 << 7)));
        USART1_TDR = (uint8_t)*s++;
    }
}

static void uart_putnum(uint16_t v)
{
    char b[6]; int n = 0;
    if (v == 0) b[n++] = '0';
    while (v) { b[n++] = '0' + v % 10; v /= 10; }
    char o[7]; int k = 0;
    while (n) o[k++] = b[--n];
    o[k] = 0;
    uart_puts(o);
}

/* collect bytes from the DMA buffer into 'line'; sets line_ready on CR/LF */
static void uart_poll(void)
{
    while (!line_ready) {
        uint16_t head = RXBUF_SIZE - (uint16_t)DMA1_CNDTR3;
        if (head >= RXBUF_SIZE) head = 0;
        if (rx_tail == head) break;
        uint8_t c = rxbuf[rx_tail];
        rx_tail = (rx_tail + 1) % RXBUF_SIZE;
        if (c == '\r' || c == '\n') {
            if (line_len) { line[line_len] = 0; line_ready = 1; }
        } else if (line_len < sizeof(line) - 1) {
            line[line_len++] = (char)c;
        }
    }
}

/* ---------------- WS2812 low level (PA4) ---------------- */
static inline void bit1(void)
{
    GPIOA_BSRR = (1 << 4);
    NOP10(); NOP10(); NOP10();
    GPIOA_BSRR = (1 << (4 + 16));
    NOP5();
}
static inline void bit0(void)
{
    GPIOA_BSRR = (1 << 4);
    NOP10();
    GPIOA_BSRR = (1 << (4 + 16));
    NOP10(); NOP10(); NOP5();
}
static void send_byte(uint8_t b)
{
    for (int i = 7; i >= 0; i--) { if (b & (1 << i)) bit1(); else bit0(); }
}

/* ---------------- strip buffer API (like BASCOM Rainbow) ---------------- */
static void px_set(int i, uint8_t r, uint8_t g, uint8_t b)
{
    if (i < 0 || i >= STRIP_LEN) return;
    px[i].r = r; px[i].g = g; px[i].b = b;
}
static void px_clear(void)
{
    for (int i = 0; i < STRIP_LEN; i++) { px[i].r = 0; px[i].g = 0; px[i].b = 0; }
}
static void strip_show(void)                 /* Rb_send */
{
    for (int i = 0; i < STRIP_LEN; i++) {
        send_byte(px[i].g); send_byte(px[i].r); send_byte(px[i].b);
    }
    for (volatile int k = 0; k < 1200; k++); /* latch gap > 50 us */
    uart_poll();
    if (line_ready && booted) longjmp(jb, 1); /* new command arrived -> abandon effect */
}
static void strip_clear(void) { px_clear(); strip_show(); }          /* Rb_clearstripe */
static void strip_fill(uint8_t r, uint8_t g, uint8_t b)               /* Rb_fillstripe  */
{
    for (int i = 0; i < STRIP_LEN; i++) { px[i].r = r; px[i].g = g; px[i].b = b; }
    strip_show();
}
static void clampse(int *from, int *to)
{
    if (*from < 0) *from = 0;
    if (*to >= STRIP_LEN) *to = STRIP_LEN - 1;
}
static void shift_right(int from, int to)    /* towards higher index, first becomes black */
{
    clampse(&from, &to);
    for (int i = to; i > from; i--) px[i] = px[i - 1];
    px[from].r = px[from].g = px[from].b = 0;
}
static void shift_left(int from, int to)
{
    clampse(&from, &to);
    for (int i = from; i < to; i++) px[i] = px[i + 1];
    px[to].r = px[to].g = px[to].b = 0;
}
static void rotate_right(int from, int to)
{
    clampse(&from, &to);
    pixel_t last = px[to];
    for (int i = to; i > from; i--) px[i] = px[i - 1];
    px[from] = last;
}
static void rotate_left(int from, int to)
{
    clampse(&from, &to);
    pixel_t first = px[from];
    for (int i = from; i < to; i++) px[i] = px[i + 1];
    px[to] = first;
}

#define SETC(i)     px_set((i), cr, cg, cb)
#define COL(a,b,c)  do { cr = (a); cg = (b); cb = (c); } while (0)
#define COLX()      COL(xr, xg, xb)
#define COLRND()    COL(rnd(xr), rnd(xg), rnd(xb))
#define show()      strip_show()

/* ---------------- time helpers (Time1 / Time2) ---------------- */
static void chekm(void)
{
    if (tim1 > 999 || tim1 < 1) tim1 = 1;
    if (tim2 > 999 || tim2 < 1) tim2 = 1;
}
static void wait_abortable(uint16_t ms)
{
    for (uint32_t k = 0; k <= ms; k++) {
        delay_1ms();
        uart_poll();
        if (line_ready) longjmp(jb, 1);
    }
}
static void time1(void) { chekm(); wait_abortable(tim1); }
static void time2(void) { chekm(); wait_abortable(tim2); }

static void set5up(int nd) { for (int k = 0; k < 5; k++) SETC(nd + k); }
static void set5dn(int nd) { for (int k = 0; k < 5; k++) SETC(nd - k); }

