static void e_star_run_slow(void)
{
    if (chc == 0) { ado = led; chc = 1; }
    if (ado == 1) chc = 0;
    for (int nd = 0; nd <= ado; nd += 2) {
        if (mx == 0) COLX(); else COLRND();
        SETC(nd); SETC(nd + 1);
        show(); time1(); px_clear();
    }
    if (mx == 0) COL(222,222,222); else COL(rnd(222), rnd(222), rnd(222));
    int dv = 0;
    if (ado > 10) {
        dv = ado / 10;
        for (int nd = ado; nd <= ado + dv; nd++) SETC(nd);
    } else {
        SETC(ado);
    }
    show(); time2();
    if (chc == 1) { if (ado > 10) ado -= dv; else ado--; }
}
static void e_star_runreturn_slow(void)
{
    COLX();
    for (int nd = 0; nd <= led; nd += 2) { SETC(nd); SETC(nd+1); SETC(nd+2); show(); time1(); px_clear(); }
    for (int nd = led; nd >= 0; nd -= 2) { SETC(nd); SETC(nd+1); SETC(nd+2); show(); time2(); px_clear(); }
}
