static void e_snak_growup_slow(void)
{
    COLX();
    for (int nd = 1; nd <= 4; nd++) SETC(nd);
    show();
    if (t_g < led) t_g += 5;
    if (t_g >= led) t_g = 1;
    for (int n = 1; n <= led - t_g; n++) { shift_right(0, led); time1(); show(); }
    for (int nd = led - 1; nd >= led - 3; nd--) { SETC(nd); show(); }
    for (int n = 1; n <= led - t_g; n++) { shift_left(0, led); time2(); show(); }
}
static void e_star_playful(void)
{
    COLX();
    for (int nd = 1; nd <= 4; nd++) SETC(nd);
    show();
    int yfd = rnd(5);
    if (t_g < led) t_g += yfd;
    if (t_g >= led) t_g = 1;
    for (int n = 1; n <= led - t_g; n++) { shift_right(0, led); time1(); show(); }
    int xfd = rnd(5);
    for (int nd = led - 1; nd >= led - xfd; nd -= 5) { SETC(nd); show(); }
    int vfd = rnd(t_g);
    for (int n = 1; n <= led - vfd; n++) { shift_left(0, led); time2(); show(); }
}
static void e_snak_star_playful(void)
{
    if (led < 22) led = 22;
    int pp = rnd(10); if (pp == 0) pp = 1;
    COLX();
    for (int nd = 1; nd <= pp; nd++) { SETC(nd); show(); }

    pp = rnd(10); if (pp == 0) pp = 1;
    if (t_g < led) t_g += 1;
    if (t_g >= led) t_g = 1;
    t_g = rnd(t_g); t_g += pp; if (t_g == 0) t_g = 1;
    for (int n = 1; n <= led - t_g; n += pp) { shift_right(0, led); show(); time1(); }
    for (int nd = led - 1; nd >= led - t_g; nd -= 3) { if (nd > 0) { SETC(nd); show(); } }
    pp = rnd(10); if (pp == 0) pp = 3;
    for (int n = 1; n <= led - t_g; n += pp) { shift_left(0, led); show(); time2(); }

    pp = rnd(10); if (pp == 0) pp = 1;
    pp = rnd(10); if (pp == 0) pp = 1;
    if (t_g < led) t_g += 1;
    if (t_g >= led) t_g = 1;
    t_g = rnd(t_g); t_g += pp; if (t_g == 0) t_g = 1;
    int md = rnd(led); if (md < t_g) md = t_g + 1;
    for (int n = 1; n <= md - t_g; n += pp) {
        int jd = led - pp;
        if (n > 0) { SETC(n); show(); }
        if (jd > 0) { SETC(jd); show(); }
        time1();
    }
    for (int nd = led - t_g; nd >= led - 1; nd -= 3) { if (nd > 0) { SETC(nd); show(); } }
    pp = rnd(10); if (pp == 0) pp = 3;
    for (int n = led - t_g; n <= 1; n += pp) { shift_right(0, led); show(); time2(); }
    for (int nd = 1; nd <= pp; nd++) { SETC(nd); show(); }
}
static void e_star_fillers(void)
{
    if (ado < led) ado++;
    if (ado == led) ado = 1;
    COLX();
    for (int nd = 1; nd <= ado; nd += 4) { SETC(nd); show(); }
    for (int n = 1; n >= led - ado; n -= 4) { shift_right(0, led); time1(); show(); }
    for (int nd = led - 1; nd >= led - ado; nd -= 5) { SETC(nd); show(); }
    for (int n = 1; n <= led - ado; n++) { shift_left(0, led); time2(); show(); }
}
static void e_movable_light(void)
{
    uint8_t xf = rnd(xr), yf = rnd(xg), vf = rnd(xb);
    for (int nd = 0; nd <= led; nd++) {
        COL(222,222,222);
        SETC(nd + 3); SETC(nd + 2); SETC(nd + 1);
        COL(xf, yf, vf);
        SETC(nd);
        time1(); show();
    }
    xf = rnd(xr); yf = rnd(xg); vf = rnd(xb);
    for (int nd = led; nd >= 0; nd--) {
        COL(222,222,222);
        SETC(nd); SETC(nd + 1); SETC(nd + 2);
        COL(xf, yf, vf);
        SETC(nd + 3);
        time2(); show();
    }
}
