static void e_breathing(void)
{
    uint8_t a1 = xr, a2 = xg, a3 = xb;
    for (int ll = 0; ll <= 255; ll++) {
        if (a1 == 1 || a2 == 1 || a3 == 1) break;
        if (a1 > 1) a1--;
        if (a2 > 1) a2--;
        if (a3 > 1) a3--;
        strip_fill(a1, a2, a3);
        time1();
    }
    for (int ll = 0; ll <= 255; ll++) {
        if (a1 == xr || a2 == xg || a3 == xb) break;
        if (a1 < xr) a1++;
        if (a2 < xg) a2++;
        if (a3 < xb) a3++;
        strip_fill(a1, a2, a3);
        time2();
    }
}
static void e_percolate_run(void)
{
    COLX();
    int jk = led / 2;
    for (int nd = 0; nd <= jk; nd++) { SETC(nd); SETC(led - nd); time1(); show(); px_clear(); }
}
static void e_percolate_return(void)
{
    COLX();
    int jk = led / 2;
    for (int nd = jk; nd >= 0; nd--) { SETC(nd); SETC(led - nd); delay_ms(1); show(); px_clear(); }
}
static void second_color_min10(void)
{
    COLRND();
    if (cr < 10) cr = 10;
    if (cg < 10) cg = 10;
    if (cb < 10) cb = 10;
}
static void e_snak_1_2_run(void)
{
    px_clear(); COLX();
    for (int nd = 0; nd <= led; nd += 2) { SETC(nd); show(); time1(); }
    second_color_min10();
    for (int nd = 1; nd <= led; nd += 2) { SETC(nd); show(); time2(); }
}
static void e_snak_1_2_return(void)
{
    int dv = led + 1;
    px_clear(); COLX();
    for (int nd = led; nd >= 0; nd -= 2) { SETC(nd); show(); time1(); }
    second_color_min10();
    for (int nd = dv; nd >= 0; nd -= 2) { SETC(nd); show(); time2(); }
}
static void e_snak_1_2_run_rev(void)
{
    px_clear(); COLX();
    for (int nd = 0; nd <= led; nd += 2) { SETC(nd); show(); time1(); }
    second_color_min10();
    for (int nd = led; nd >= 0; nd -= 2) { SETC(nd); show(); time2(); }
}
static void e_snak_1_2_return_rev(void)
{
    px_clear(); COLX();
    for (int nd = led; nd >= 0; nd -= 2) { SETC(nd); show(); time1(); }
    second_color_min10();
    for (int nd = 0; nd <= led; nd += 2) { SETC(nd); show(); time2(); }
}
static void e_snak_relax_run(void)
{
    px_clear(); COLX();
    if (cr > 10) dx = cr / 10;
    if (cg > 10) dy = cg / 10;
    if (cb > 10) dz = cb / 10;
    COL(0,0,0);
    for (int nd = led; nd >= led - 10; nd--) { cr += dx; cg += dy; cb += dz; SETC(nd); }
    for (int nd = led - 11; nd >= led - 20; nd--) { cr -= dx; cg -= dy; cb -= dz; SETC(nd); }
    show();
    for (int n = 0; n <= led; n++) { shift_left(0, led); time1(); show(); }
}
static void e_snak_relax_return(void)
{
    px_clear(); COLX();
    if (cr > 10) dx = cr / 10;
    if (cg > 10) dy = cg / 10;
    if (cb > 10) dz = cb / 10;
    COL(0,0,0);
    for (int nd = 0; nd <= 10; nd++) { cr += dx; cg += dy; cb += dz; SETC(nd); }
    for (int nd = 11; nd <= 21; nd++) { cr -= dx; cg -= dy; cb -= dz; SETC(nd); }
    show();
    for (int n = 0; n <= led; n++) { shift_right(0, led); time1(); show(); }
}
static void rainbow_rotate(void)
{
    for (int n = 0; n <= led; n++) {
        if (rainbo == 0) rotate_right(0, led); else rotate_left(0, led);
        time1(); show();
    }
}
static void e_snak_rainbow(void)
{
    for (int i = 0; i < 50; i++) {
        COLRND();
        if (cr > 10) dx = cr / 10;
        if (cg > 10) dy = cg / 10;
        if (cb > 10) dz = cb / 10;
        COL(0,0,0);
        int bfd = 20 * i, jk = 10 + bfd, lk = 20 + bfd;
        for (int nd = bfd; nd <= jk; nd++) { cr += dx; cg += dy; cb += dz; SETC(nd); }
        for (int nd = jk; nd <= lk; nd++)  { cr -= dx; cg -= dy; cb -= dz; SETC(nd); }
    }
    show();
    rainbow_rotate();
}
static void e_snak_rainbow_lp(void)
{
    for (int i = 0; i < 50; i++) {
        int bfd = 20 * i, jk = 10 + bfd, lk = 20 + bfd;
        for (int nd = bfd; nd <= jk; nd++) { COLRND(); SETC(nd); }
        for (int nd = jk; nd <= lk; nd++)  { COLRND(); SETC(nd); }
    }
    show();
    rainbow_rotate();
}
static void e_snak_rainbow_bl(void)
{
    px_clear();
    strip_clear();
    for (int i = 0; i < 50; i++) {
        int bfd = 20 * i, lk = 20 + bfd;
        for (int nd = bfd; nd <= lk; nd++) { COLRND(); SETC(nd); }
    }
    show();
    time1();
    rotate_left(0, led);
    show();
    px_clear();
    time2();
}

/* ======================= DANCE DISPATCH (Modh) ======================= */
static uint8_t pick(uint8_t v)
{
    switch (v) {
    case 251: return rnd(15);
    case 252: return rnd(30);
    case 253: return rnd(60);
    case 254: return rnd(120);
    case 255: return rnd(250);
    default:  return v;
    }
}

static void dance_step(void)
{
    if (led == 0) led = 1;
    if (led > STRIP_LEN - 1) led = STRIP_LEN - 1;
    uint8_t dans = (dan == 99) ? (uint8_t)rnd(55) : (uint8_t)(dan - 1);
    xr = pick(rr); xg = pick(gg); xb = pick(bb);

    switch (dans) {
    case 0:  e_snak_run_slow(); break;
    case 1:  e_snak_return_slow(); break;
    case 2:  e_snak_run_slow(); e_snak_return_slow(); break;
    case 3:  e_snak_run_fast(); break;
    case 4:  e_snak_return_fast(); break;
    case 5:  e_snak_run_fast(); e_snak_return_fast(); break;
    case 6:  e_snak_run_slow_random(); break;
    case 7:  e_snak_return_slow_random(); break;
    case 8:  e_snak_run_slow_random(); e_snak_return_slow_random(); break;
    case 9:  e_snak_run_fast_random(); break;
    case 10: e_snak_return_fast_random(); break;
    case 11: e_snak_run_fast_random(); e_snak_return_fast_random(); break;
    case 12: e_snak_runreturn_slow_random(); break;
    case 13: nnb = 0; e_half_snak_out_mid_slow(); break;
    case 14: nnb = 1; e_half_snak_out_mid_slow(); break;
    case 15: e_half_snak_out_mid_slow(); nnb ^= 1; break;
    case 16: e_half_half_right_slow(); break;
    case 17: e_half_half_left_slow(); break;
    case 18: mx = 0; e_star_run_slow(); break;
    case 19: mx = 1; e_star_run_slow(); break;
    case 20: e_star_runreturn_slow(); break;
    case 21: e_star_run_fast(); break;
    case 22: e_star_return_fast(); break;
    case 23: e_star_run_fast(); e_star_return_fast(); break;
    case 24: e_snak_growup_slow(); break;
    case 25: e_star_playful(); break;
    case 26: e_snak_star_playful(); break;
    case 27: e_star_fillers(); break;
    case 28: e_movable_light(); break;
    case 29: e_snak_runreturn_colored(); break;
    case 30: e_diamonds_blink_slow(); break;
    case 31: e_diamonds_blink_fast(); break;
    case 32: e_diamonds_blink_faster(); break;
    case 33: e_disco(); break;
    case 34: e_fillstripe_color(); break;
    case 35: e_breathing(); break;
    case 36: e_percolate_run(); break;
    case 37: e_percolate_return(); break;
    case 38: e_percolate_run(); e_percolate_return(); break;
    case 39: e_snak_1_2_run(); break;
    case 40: e_snak_1_2_return(); break;
    case 41: e_snak_1_2_run(); e_snak_1_2_return(); break;
    case 42: e_snak_1_2_run_rev(); break;
    case 43: e_snak_1_2_return_rev(); break;
    case 44: e_snak_1_2_run_rev(); e_snak_1_2_return_rev(); break;
    case 45: e_snak_relax_run(); break;
    case 46: e_snak_relax_return(); break;
    case 47: e_snak_relax_run(); e_snak_relax_return(); break;
    case 48: rainbo = 0; e_snak_rainbow(); break;
    case 49: rainbo = 1; e_snak_rainbow(); break;
    case 50: rainbo = 0; e_snak_rainbow(); rainbo = 1; e_snak_rainbow(); break;
    case 51: rainbo = 0; e_snak_rainbow_lp(); break;
    case 52: rainbo = 1; e_snak_rainbow_lp(); break;
    case 53: rainbo = 0; e_snak_rainbow_lp(); rainbo = 1; e_snak_rainbow_lp(); break;
    case 54: e_snak_rainbow_bl(); break;
    default: break;
    }
}

/* ======================= COMMAND PARSER ======================= */
static void paint(int s, int e, uint8_t r, uint8_t g, uint8_t b)
{
    for (int i = s; i <= e; i++) px_set(i, r, g, b);
    strip_show();
}

static void repaint_slots(void)
{
    for (int i = 1; i <= NUM_SLOTS; i++)
        if (slot_used[i])
            for (int p = slot_s[i]; p <= slot_e[i]; p++)
                px_set(p, slot_r[i], slot_g[i], slot_b[i]);
    strip_show();
}

static void mem_clear(void)
{
    for (int i = 0; i <= NUM_SLOTS; i++) slot_used[i] = 0;
    strip_clear();
}

static uint16_t read_num(const char *b, uint8_t n, uint8_t *i, uint8_t maxd, uint8_t *digits)
{
    uint16_t v = 0; uint8_t d = 0;
    while (*i < n && b[*i] >= '0' && b[*i] <= '9' && d < maxd) {
        v = v * 10 + (b[*i] - '0'); (*i)++; d++;
    }
    *digits = d;
    return v;
}

static void process_line(void)
{
    char b[82];
    uint8_t n = line_len, s = 0;
    for (uint8_t k = 0; k < n; k++) b[k] = line[k];
    b[n] = 0;
    line_len = 0;
    line_ready = 0;

    while (s < n && (uint8_t)b[s] <= ' ') s++;       /* trim left */

    /* ---- address change: CH<old>=<new> ---- */
    if (s + 1 < n && (b[s] == 'C' || b[s] == 'c') && (b[s + 1] == 'H' || b[s + 1] == 'h')) {
        uint8_t i = s + 2, d;
        uint16_t old = read_num(b, n, &i, 3, &d);
        if (i < n && b[i] == '=') {
            i++;
            uint16_t nw = read_num(b, n, &i, 3, &d);
            if (old == addr && d && nw > 0 && nw < 99) {
                addr = (uint8_t)nw;
                uart_puts("New Address=");
                uart_putnum(addr);
                uart_puts("\r\n");
            }
        }
        return;
    }

    uint8_t target = 0, matched = 0, old_dan = dan;

    for (uint8_t i = s; i < n; i++) {
        char c = b[i];
        if (c >= 'a' && c <= 'z') c -= 32;
        if (!(c=='A'||c=='D'||c=='R'||c=='G'||c=='B'||c=='M'||c=='S'||c=='E')) continue;
        uint8_t j = i + 1, d;
        uint16_t v = read_num(b, n, &j, 3, &d);
        if (d == 0) continue;
        i = j - 1;

        if (c == 'A') { if (v > 0 && v < 100) target = (uint8_t)v; continue; }
        if (!(target == addr || target == 99)) continue;
        matched = 1;

        switch (c) {
        case 'D': if (v <= 55 || v == 99) dan = (uint8_t)v; break;
        case 'R': if (v < 256) rr = (uint8_t)v; break;
        case 'G': if (v < 256) gg = (uint8_t)v; break;
        case 'B': if (v < 256) bb = (uint8_t)v; break;
        case 'M': if (v < 1000) led = v; break;
        case 'S': if (dan == 0) ns = v; else tim1 = v; break;
        case 'E': if (dan == 0) nf = v; else tim2 = v; break;
        }
    }
    if (!matched) return;

    if (dan != old_dan) {                 /* mode changed: start from a clean strip */
        strip_clear();
        if (dan == 0) repaint_slots();
    }

    if (dan == 0) {
        if (led > 0 && led <= NUM_SLOTS) {            /* M1..M98: remember + draw */
            slot_used[led] = 1;
            slot_s[led] = ns; slot_e[led] = nf;
            slot_r[led] = rr; slot_g[led] = gg; slot_b[led] = bb;
            paint(ns, nf, rr, gg, bb);
            delay_ms(1);
        } else {
            switch (led) {
            case 0:   paint(ns, nf, rr, gg, bb); delay_ms(1); break;   /* preview */
            case 996: mem_clear(); break;
            case 997: strip_clear(); delay_ms(100); break;
            case 998: strip_fill(rr, gg, bb); delay_ms(100); break;
            case 999: strip_fill(rr, gg, bb); delay_ms(1); break;
            default:  break;
            }
        }
    } else {
        if (led < 1) led = 1;
        if (led > 999) led = 999;
        chekm();
    }
}

/* ======================= MAIN ======================= */
int main(void)
{
    clock_init_48mhz();
    systick_init();

    RCC_AHBENR |= (1 << 17) | (1 << 0);          /* GPIOA + DMA1 clocks */
    GPIOA_MODER &= ~(3 << (4 * 2));
    GPIOA_MODER |= (1 << (4 * 2));               /* PA4 output */
    GPIOA_OSPEEDR |= (3 << (4 * 2));
    GPIOA_BSRR = (1 << (4 + 16));

    uart_init();

    setjmp(jb);                                  /* effects abort back to here */
    if (!booted) { strip_clear(); booted = 1; }

    for (;;)
    {
        uart_poll();
        if (line_ready)      process_line();
        else if (dan > 0)    dance_step();
    }
}
